# Generated by build.py from recipe.yml for recipe smtp-resend-after-a-dropped-connection. Do not edit.
set -e
cd "$(dirname "$0")"
awk '{printf "%s\r\n", $0}' > order.eml <<'EOF'
From: app@example.com
To: ann@example.com
Subject: Order 1042 has shipped

Your order is on its way.
EOF
surl -v --log-file surl.log --mail-domain example.com --mailbox app@example.com:apppass --mailbox ann@example.com:annpass --fault "drop;scheme=smtp;times=1" imap://127.0.0.1:8081/ smtp://127.0.0.1:8080/ &
sleep 1
curl -s --retry 30 --retry-connrefused --retry-delay 1 -X NOOP imap://127.0.0.1:8081/
curl -s --retry 30 --retry-connrefused --retry-delay 1 -X NOOP imap://127.0.0.1:8083/
curl -s --retry 30 --retry-connrefused --retry-delay 1 -X NOOP imap://127.0.0.1:8085/
curl -s --retry 30 --retry-connrefused --retry-delay 1 -X NOOP imap://127.0.0.1:8087/
curl -s --retry 1 --retry-all-errors --retry-delay 1 --crlf -u app@example.com:apppass --mail-from app@example.com --mail-rcpt ann@example.com -T order.eml -w "%{response_code} %{num_retries}\n" smtp://127.0.0.1:8080/example.com && curl -s -u ann@example.com:annpass -X "STATUS INBOX (MESSAGES)" imap://127.0.0.1:8081/
kill $(jobs -p)
